const fn kernel(offset: u32, size: u32, grf: u8, bindings: u8) -> ShaderKernelMetadata {
    ShaderKernelMetadata {
        code_offset_bytes: offset,
        code_size_bytes: size,
        code_alignment_bytes: 64,
        ksp_offset_bytes: 0,
        dispatch_mode: DispatchMode::Simd8,
        grf_start_register: grf,
        grf_used: 128,
        push_constant_bytes: 0,
        binding_table_entry_count: bindings,
        sampler_count: 0,
    }
}
pub(crate) static PIPELINE: TrianglePipeline = TrianglePipeline {
    vs: TriangleVertexShader {
        code: &VERTEX,
        meta: TriangleVertexShaderMetadata {
            kernel: kernel(0, VERTEX.len() as u32 * 4, 2, 4),
            max_threads: 546,
            urb_entry_output_length: 1,
        },
    },
    ps: TrianglePixelShader {
        code: &FRAGMENT,
        meta: TrianglePixelShaderMetadata {
            kernel: kernel(((VERTEX.len() as u32 * 4) + 63) & !63, FRAGMENT.len() as u32 * 4, 4, 1),
            num_varying_inputs: 3,
            uses_vmask: true,
            computed_stencil: false,
            persample_dispatch: false,
            computed_depth_mode: 0,
            flat_inputs: 0,
        },
    },
};
pub(crate) fn matches(pipeline: &TrianglePipeline) -> bool {
    core::ptr::eq(pipeline.vs.code.as_ptr(), VERTEX.as_ptr())
        && core::ptr::eq(pipeline.ps.code.as_ptr(), FRAGMENT.as_ptr())
}
